&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Kurumu kişiye, hukuku keyfe, y&amp;ouml;netimi talimata teslim etmeyeceğiz!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Hukuk devletini&amp;rdquo; yeniden hakim kılacağız! &amp;Uuml;lke kararnamelerle değil, yasalarla y&amp;ouml;netilecek. &amp;Uuml;lkedeki tek ger&amp;ccedil;ek saray; &amp;ldquo;Adalet Sarayı&amp;rdquo; olacak.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Kurumların kilit noktalarına yerleştirilen partizan kadrolaşmayı, tasfiye edeceğiz!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Devlet kadrolarını &amp;ldquo;parti b&amp;uuml;rosu&amp;rdquo; gibi kullanan anlayışı sona erdireceğiz!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Cumhurbaşkanlığı H&amp;uuml;k&amp;uuml;met sistemine ge&amp;ccedil;tikten sonra Yapılan t&amp;uuml;m kamu ihalelerini denetleyeceğiz!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ne yapacağız biliyor musunuz? &amp;ldquo;Yolsuzlukla M&amp;uuml;cadele Bakanlığı&amp;rdquo; kuracağız!&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bitmedi! Devlet televizyonunu iktidarın değil, &amp;ldquo;milletin televizyonu&amp;rdquo; haline getireceğiz! Yanii, bizim iktidarımızda; devlet televizyonunda, muhalefet partilerini de g&amp;ouml;rebileceksiniz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;RT&amp;Uuml;K&amp;rsquo;&amp;uuml; yeniden yapılandıracağız! G&amp;uuml;nd&amp;uuml;z kuşağı programlarını, mafya ve entrika dizilerini tarihin karanlık sayfalarına g&amp;ouml;meceğiz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Haa bu arada, tabiki T&amp;Uuml;İK&amp;rsquo;i unutmadık. B&amp;uuml;t&amp;uuml;n T&amp;Uuml;İK y&amp;ouml;neticilerine, pazardan alışveriş yapma zorunluluğu getireceğiz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ge&amp;ccedil;miş d&amp;ouml;nemde g&amp;ouml;rev yapan bakanların, milletvekillerinin, &amp;uuml;st d&amp;uuml;zey b&amp;uuml;rokratların ve bunların yakın aile &amp;ccedil;evrelerinin mal varlığı artışlarını hukuki &amp;ccedil;er&amp;ccedil;evede incelemeye alacağız!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;G&amp;ouml;rev alan herkes şunu bilsin: &amp;ldquo;Bu makamlar ganimet değil, emanettir.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Değerli dava kardeşlerim, Şunun altını &amp;ouml;zellikle &amp;ccedil;izmek istiyorum: Amacımız; İntikam almak, İnsanları fişlemek, Devr-i sabık yapmak değil raydan &amp;ccedil;ıkarılan devleti tekrar rayına oturtmak.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;&amp;Ouml;NG&amp;Ouml;R&amp;Uuml;LEBİLİR BİR T&amp;Uuml;RKİYE TEKLİF EDİYORUZ&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;İşte biz; Bu ilkelerimiz ve projelerimizle Milletimize &amp;ldquo;&amp;ouml;ng&amp;ouml;r&amp;uuml;lebilir bir T&amp;uuml;rkiye&amp;rdquo; teklif ediyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Yarın başıma bir iş gelir mi?&amp;rdquo; sorusunu, &amp;ldquo;Yarın daha iyisi m&amp;uuml;mk&amp;uuml;n m&amp;uuml;?&amp;rdquo; sorusuna d&amp;ouml;n&amp;uuml;şt&amp;uuml;ren bir T&amp;uuml;rkiye vaat ediyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Hakkım yenir mi?&amp;rdquo; endişesini, &amp;ldquo;Emeğim korunur&amp;rdquo; g&amp;uuml;venine &amp;ccedil;eviren bir T&amp;uuml;rkiye vaat ediyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Ouml;ng&amp;ouml;r&amp;uuml;lebilir bir ekonomi, &amp;Ouml;ng&amp;ouml;r&amp;uuml;lebilir bir hukuk, &amp;Ouml;ng&amp;ouml;r&amp;uuml;lebilir bir kamu d&amp;uuml;zeni vaat ediyoruz.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;BİZİ DİĞERLERİ İLE KARIŞTIRMAYIN&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Şimdi birileri &amp;ccedil;ıkıp; &amp;ldquo;Efendim muhalefetteyken herkes b&amp;ouml;yle g&amp;uuml;zel vaatlerde bulunuyor. G&amp;uuml;zel s&amp;ouml;zler s&amp;ouml;yl&amp;uuml;yor, ama iktidar olunca değişiyor.&amp;rdquo; diyebilir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Şunu bir s&amp;ouml;yleyelim, bizi diğerleri ile karıştırmayın.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Biz tutamayacağımız s&amp;ouml;z&amp;uuml; asla vermeyiz, s&amp;ouml;z verdiğimizi de mutlaka yaparız!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Ccedil;&amp;uuml;nk&amp;uuml; biz; değil 25 yıl, 11 ayda D-8&amp;rsquo;leri kuranlarız! Biz, değil 25 yıl; 11 ayda cumhuriyet tarihinin tek ve ilk denk b&amp;uuml;t&amp;ccedil;esini yapanlarız! Biz , meclise Amerikan tezkeresi değil; &amp;ldquo;Filistin Tezkeresi&amp;rdquo; getirenleriz. Evet! Biz, 25 yıl değil, 25 ay değil, 25 g&amp;uuml;n değil bir gecede Kıbrıs Barış Harekatı&amp;rsquo;nı yapanlarız.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;MAKSADIMIZ KENDİ MEŞALEMİZİ YAKMAKTIR&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Değerli dava kardeşlerim, Kıymetli teşkilat mensuplarımız, Konuşmamın bu b&amp;ouml;l&amp;uuml;m&amp;uuml;nde; doğrudan sizlere sesleniyorum!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Ccedil;&amp;uuml;nk&amp;uuml;; Burada anlattığımız her şeyi ger&amp;ccedil;ekleştirecek olan; sizleriniz! Kurduğumuz bu b&amp;uuml;y&amp;uuml;k hayali; ger&amp;ccedil;eğe d&amp;ouml;n&amp;uuml;şt&amp;uuml;recek olan sizlersiniz! Saadet Partimizi; iktidar yapacak olan sizlersiniz!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Siyasette, en b&amp;uuml;y&amp;uuml;k strateji: İnanmaktır!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Davaya inanmak! S&amp;ouml;ze inanmak! Kadroya inanmak! Ve her şeyin &amp;ouml;tesinde, kendine inanmak!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Ccedil;&amp;uuml;nk&amp;uuml; inanmayan, inandıramaz! Y&amp;uuml;reğinde ateş taşımayan, başkasının y&amp;uuml;reğini tutuşturamaz!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Amacımız karanlığı lanetlemek değil, kendi meşalemizi yakmak! Yanacağız, ama yakmayacağız Yorulacağız, ama yormayacağız &amp;Uuml;z&amp;uuml;leceğiz, ama &amp;uuml;zmeyeceğiz Seveceğiz, sevdireceğiz.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;BESMELEMİZİ &amp;Ccedil;EKİYORUZ!&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Sizlerden, yeniden &amp;ldquo;BİSMİLLAH&amp;rdquo; demenizi istiyorum. &amp;Ccedil;&amp;uuml;nk&amp;uuml;, biz biliyoruz ki; &amp;ldquo;Bir işteki muvaffakiyet, &amp;ccedil;ekilen besmeledeki samimiyet kadardır.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ardından yakamıza, şerefle rozetlerimizi takacağız. Ve hep birlikte, Anadolu&amp;rsquo;nun yollarına d&amp;uuml;şeceğiz. İnsanımız bizleri bekliyor! Biz, onlara, hedeflerimizi anlatacağız! Temiz siyasetin, ahlaklı siyasetin m&amp;uuml;mk&amp;uuml;n olduğunu g&amp;ouml;stereceğiz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Değerli kardeşlerim; Biz &amp;uuml;ye yapacağız!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Size dağıtılan &amp;ccedil;antalarda 9 adet &amp;uuml;ye formu var. Neden 8 değil, 10 değil de 9? &amp;Ccedil;&amp;uuml;nk&amp;uuml; besmele 9 harften oluşur. Ve biz bug&amp;uuml;n yeniden &amp;ldquo;bismillah&amp;rdquo; diyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ve -inşallah- ge&amp;ccedil;tiğimiz d&amp;ouml;nemde olduğu gibi yine milletimiz tevecc&amp;uuml;h g&amp;ouml;sterecek, yine &amp;uuml;ye sayısını en &amp;ccedil;ok artıran 1. parti olacağız! Şunu unutmayın! Şimdiye kadar olduğu gibi, Hi&amp;ccedil; kimse; bize iktidarı altın tepside sunmayacak!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Gece g&amp;uuml;nd&amp;uuml;z &amp;ccedil;alışacağız! Ter d&amp;ouml;keceğiz! Bedel &amp;ouml;deyeceğiz! Herkes bilsin ki, o iktidarı, tırnaklarımızla kazıyarak alacağız!&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Kıymetli gen&amp;ccedil; kardeşlerim! Biz, biiiz bozuk yolu da se&amp;ccedil;meyiz yolumuzdan da d&amp;ouml;nmeyiz!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Biz bu yolu sizinle, g&amp;ouml;z g&amp;ouml;ze, omuz omuza, birlikte y&amp;uuml;r&amp;uuml;yeceğiz inşallah!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Hi&amp;ccedil; ş&amp;uuml;pheniz olmasın Eğriye eğri, doğruya da doğru diyeceğiz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Sevgili gen&amp;ccedil;ler, Allah sayılarınızı artırsın, Rabbim azminizi artırsın, Mevla&amp;rsquo;m emeğinizi zayi etmesin, Allah sizlerden razı olsun!&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;SE&amp;Ccedil;İMLERE HAZIRIZ&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Aziz dava kardeşlerim, Hi&amp;ccedil; ş&amp;uuml;phesiz, hedefimiz ilk se&amp;ccedil;imler! Şunun iyi bilinmesini isterim; Se&amp;ccedil;imler, şahıslar i&amp;ccedil;in değildir! Biz se&amp;ccedil;imleri, milletimize hizmet i&amp;ccedil;in bir fırsat olarak g&amp;ouml;r&amp;uuml;yoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;T&amp;uuml;rkiye&amp;rsquo;nin mevcut sistemi i&amp;ccedil;erisinde &amp;ldquo;se&amp;ccedil;im&amp;rdquo; denince artık hep ittifaklar g&amp;uuml;ndeme geliyor. Buradan t&amp;uuml;m samimiyetimle ilan ediyorum.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bizim derdimiz, İnandığımız değerlerin, Ortaya koyduğumuzun ilkelerin y&amp;ouml;netimde olmasıdır. Bize &amp;ldquo;niye onlarla g&amp;ouml;r&amp;uuml;ş&amp;uuml;yorsunuz?&amp;rdquo;, &amp;ldquo;niye bunlarla g&amp;ouml;r&amp;uuml;şm&amp;uuml;yorsunuz?&amp;rdquo; diyenler var&amp;hellip; Bunlara hii&amp;ccedil; aldırmıyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Tek odağımız var: G&amp;ouml;r&amp;uuml;şt&amp;uuml;ğ&amp;uuml;m&amp;uuml;z her kesimle ilke ve prensiplerimiz ışığında geleceği inşa etmek i&amp;ccedil;in buradayız.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Saadet Partisi burada, kadrolarımız işte bu salonda, irademiz işte, bu divanda, heyecanımız balkonlardan taşıyor!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Biz, hazırız!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ara se&amp;ccedil;ime de hazırız! Erken se&amp;ccedil;ime de hazırız! Baskın se&amp;ccedil;ime de hazırız! Yerel se&amp;ccedil;ime de hazırız! Genel se&amp;ccedil;ime de hazırız! Bir yıl sonra da, hazırız! Bir ay sonra da, hazırız! Yarın da, hazırız!&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;BUG&amp;Uuml;NDEN İTİBAREN SE&amp;Ccedil;İM &amp;Ccedil;ALIŞMALARIMIZ BAŞLAMIŞTIR!&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;İşte bug&amp;uuml;n, Bu muazzam salonda T&amp;uuml;m teşkilatımızın katılımıyla ger&amp;ccedil;ekleştirdiğimiz T&amp;uuml;rkiye Divanında, &amp;ldquo;Se&amp;ccedil;im Seferberliğimizi&amp;rdquo; t&amp;uuml;m T&amp;uuml;rkiye&amp;rsquo;ye ilan ediyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bizim, se&amp;ccedil;im takvimimiz bug&amp;uuml;nden itibaren başlamıştır. Vatana, millete hayırlı olsun!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Millete ilk ulaşan parti, biz olacağız. Kararsıza umut olan parti, biz olacağız. Gen&amp;ccedil;lere g&amp;uuml;ven veren parti, biz olacağız.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;G&amp;ouml;receksiniz! Bu &amp;ccedil;alışmalarımız sayesinde; En belirleyici unsur biz olacağız! Dengenin merkezi biz olacağız! Bu se&amp;ccedil;imlerin en etkili partisi, Saadet Partisi olacak!&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;T&amp;Uuml;RKİYE İ&amp;Ccedil;İN B&amp;Uuml;T&amp;Uuml;N G&amp;Uuml;C&amp;Uuml;M&amp;Uuml;ZLE&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Bu b&amp;uuml;y&amp;uuml;k buluşmanın ruhunu, bir kez daha hatırlatmak istiyorum.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;T&amp;uuml;rkiye Divanımızı toplarken ne dedik? &amp;ldquo;T&amp;uuml;rkiye İ&amp;ccedil;in B&amp;uuml;t&amp;uuml;n G&amp;uuml;c&amp;uuml;m&amp;uuml;zle&amp;rdquo; dedik!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Neden? &amp;Ccedil;&amp;uuml;nk&amp;uuml; bug&amp;uuml;n T&amp;uuml;rkiye, yarım bir gayreti kaldırmaz! Ben sizleri; T&amp;uuml;rkiye i&amp;ccedil;in b&amp;uuml;t&amp;uuml;n g&amp;uuml;c&amp;uuml;m&amp;uuml;zle &amp;ccedil;alışmaya &amp;ccedil;ağırıyorum! Ben sizleri; adil bir d&amp;uuml;zen i&amp;ccedil;in b&amp;uuml;t&amp;uuml;n g&amp;uuml;c&amp;uuml;m&amp;uuml;zle &amp;ccedil;alışmaya &amp;ccedil;ağırıyorum! Gazze i&amp;ccedil;in, mazlum coğrafyalar i&amp;ccedil;in, b&amp;uuml;t&amp;uuml;n g&amp;uuml;c&amp;uuml;m&amp;uuml;zle &amp;ccedil;alışmaya &amp;ccedil;ağırıyorum! Var mısınız? Var mısınız? O zaman her birinizi, Ahdimizi yenilemek &amp;uuml;zere ayağa davet ediyorum.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Etkinlik, Saadet Partisi Genel Başkanı Mahmut Arıkan&amp;rsquo;ın salondaki teşkilat mensuplarına milli g&amp;ouml;r&amp;uuml;ş yemini ettirmesinin ardından tamamladı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
